const msg = $input.first().json;
const m = msg.message || {};
const voice = m.voice || m.audio || null;
return [{ json: {
  raw_text: m.text || m.caption || '',
  chat_id: m.chat && m.chat.id,
  username: (m.from && m.from.username) || 'unknown',
  timestamp: new Date().toISOString(),
  is_voice: !!voice,
  voice_file_id: voice ? voice.file_id : null
} }];

const r = $input.first().json;
const src = $('Extract message').first().json;
const text = (r && r.text) ? r.text.trim() : '';
return [{ json: { raw_text: text, chat_id: src.chat_id, username: src.username, timestamp: src.timestamp } }];

// Thrifty router:
//  - /task and /note are DETERMINISTIC (zero AI): dispatched straight to the tool.
//  - everything else (free text, voice, /plan, /calendar, /brain, /web) goes to
//    Rebeca, whose own local-first router keeps Claude for last resort.
const d = $input.first().json;
let text = (d.raw_text || '').trim();
const chat_id = d.chat_id;
const mm = text.match(/^(\/[a-z_]+)(?=$|\s)/i);
const cmd = mm ? mm[1].toLowerCase() : null;
const rest = mm ? text.slice(mm[1].length).trim() : text;

// Deterministic fast paths (no LLM): dispatch the tool via assistant-core.
if (cmd === '/task' && rest) {
  const nl = rest.indexOf('\n');
  const title = (nl === -1 ? rest : rest.slice(0, nl)).slice(0, 200);
  const description = nl === -1 ? '' : rest.slice(nl + 1).trim();
  return [{ json: { mode: 'tool', chat_id, requestBody: JSON.stringify({ name: 'create_task', input: { title, description } }) } }];
}
if (cmd === '/note' && rest) {
  return [{ json: { mode: 'tool', chat_id, requestBody: JSON.stringify({ name: 'save_note', input: { content: rest } }) } }];
}

// Everything else -> Rebeca (map remaining commands to natural language).
const MAP = {
  '/plan': 'Planifica esto: propón el plan (proyecto, tarea padre y subtareas) y pídeme confirmación antes de crearlo. ',
  '/calendar': 'Agenda en Google Calendar: ', '/cal': 'Agenda en Google Calendar: ',
  '/brain': 'Busca en mi second brain y responde con base en mis notas: ',
  '/show_brain': 'Busca en mi second brain y responde con base en mis notas: ',
  '/web': 'Busca en la web: '
};
let body = text;
if (cmd) body = (MAP[cmd] !== undefined) ? (MAP[cmd] + rest) : (rest || text);
if (!body) body = '(mensaje vacío)';
return [{ json: { mode: 'rebeca', chat_id, requestBody: JSON.stringify({ session_id: 'telegram:' + chat_id, message: body, channel: 'telegram' }) } }];

const r = $input.first().json;
let text;
if (r && r.ok !== false) {
  if (r.identifier) text = '\u2705 Tarea creada: ' + r.identifier + ' \u2014 ' + (r.title || '') + (r.url ? '\n' + r.url : '');
  else if (r.result) text = '\u2705 ' + r.result;
  else text = '\u2705 Hecho.';
} else {
  text = '\u26a0\ufe0f Error: ' + ((r && r.error) || 'desconocido');
}
const chat_id = $('Route').first().json.chat_id;
return [{ json: { text, chat_id } }];

const r = $input.first().json;
let text = (r && r.response) ? String(r.response) : '\u26a0\ufe0f Sin respuesta de Rebeca.';
text = text
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/(^|\n)#{1,6}\s*/g, '$1')
  .replace(/`{1,3}/g, '')
  .replace(/^\s*[-*]\s+/gm, '\u2022 ')
  .trim();
if (text.length > 4000) text = text.slice(0, 3990) + '\u2026';
const chat_id = $('Route').first().json.chat_id;
return [{ json: { text, chat_id } }];
